    PlaybackSettingItem("animation.video_shared_transition_speed", "视频转场速度", SettingsRootCategory.APPEARANCE_THEME, "animation_card", null, target = SettingsSearchTarget.ANIMATION, readState = { state -> state.videoSharedTransitionSpeed.label }),
